def has_monochromatic_ap3(coloring):
    n = len(coloring)
    for a in range(1, n + 1):
        for d in range(1, n + 1):
            if a + 2 * d <= n:
                if coloring[a - 1] == coloring[a + d - 1] == coloring[a + 2 * d - 1]:
                    return True
    return False

# Let's check if W(3, 3) is indeed 27.
# We can use a backtracking solver to find the maximum n for which a coloring exists.
def solve(n, num_colors):
    coloring = [None] * n
    def backtrack(idx):
        if idx == n:
            return coloring
        for color in range(num_colors):
            coloring[idx] = color
            # Check if this color creates an AP of length 3
            # Only need to check APs ending at idx
            valid = True
            for d in range(1, (idx) // 2 + 1):
                if coloring[idx] == coloring[idx - d] == coloring[idx - 2 * d]:
                    valid = False
                    break
            if valid:
                res = backtrack(idx + 1)
                if res:
                    return res
        return None
    return backtrack(0)

# Let's test for n = 27
print(solve(27, 3))
